// Settings.js
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

function Settings() {
  const [personality, setPersonality] = useState('');
  const [botName, setBotName] = useState('');  // 챗봇 이름 상태 추가
  const navigate = useNavigate();

  const handleSave = () => {
    if (personality && botName) {  // 이름과 성격이 모두 설정된 경우
      navigate('/chat', { state: { personality, botName } });
    } else {
      alert('모든 항목을 입력해주세요!');
    }
  };

  return (
    <div>
      <h2>Settings</h2>
      <label>
        Personality:
        <select onChange={(e) => setPersonality(e.target.value)}>
          <option value="">--선택--</option>
          <option value="T">현실적</option>
          <option value="F">감정적</option>
        </select>
      </label>
      <br />
      <label>
        Chatbot Name:  {/* 챗봇 이름 입력 필드 추가 */}
        <input
          type="text"
          value={botName}
          onChange={(e) => setBotName(e.target.value)}
          placeholder="챗봇의 이름을 입력하세요"
        />
      </label>
      <br />
      <button onClick={handleSave}>채팅 시작</button>
    </div>
  );
}

export default Settings;
